 4.41\n1961: Treasury 3.90, Moody's 4.35\n1962: Treasury 3.95, Moody's 4.33\n1963: Treasury 4.00, Moody's 4.26\n1964: Treasury 4.15, Moody's 4.40\n1965: Treasury 4.21, Moody's 4.49\n1966: Treasury 4.65, Moody's 5.13\n\nI'll proceed with calculating the correlation using a Python script to analyze these yield trends.\n","signature":""},{"type":"toolRequest","id":"call_e6e993b29bfb4cc0b144bdaa","toolCall":{"status":"success","value":{"name":"shell","arguments":{"command":"python3 << 'EOF'\nimport numpy as np\nfrom scipy import stats\n\n# Data from the bulletins for years 1942-1966\n# Treasury bonds and Moody's AAA corporate bonds\nyears = list(range(1942, 1967))  # 1942-1966 inclusive\n\n# Treasury yields (%)\ntreasury_yields = [\n    2.46,  # 1942\n    2.47,  # 1943\n    2.48,  # 1944\n    2.37,  # 1945\n    2.19,  # 1946\n    2.25,  # 1947\n    2.44,  # 1948\n    2.31,  # 1949\n    2.32,  # 1950\n    2.57,  # 1951\n    2.68,  # 1952\n    2.94,  # 1953\n    2.55,  # 1954\n    2.84,  # 1955\n    3.08,  # 1956\n    3.47,  # 1957\n    3.43,  # 1958\n    4.08,  # 1959\n    4.02,  # 1960\n    3.90,  # 1961\n    3.95,  # 1962\n    4.00,  # 1963\n    4.15,  # 1964\n    4.21,  # 1965\n    4.65,  # 1966\n]\n\n# Moody's AAA yields (%) - note: 1955 is 3.01 in 1967 bulletin vs 3.0x in 1960\nmoodys_yields = [\n    2.83,  # 1942\n    2.73,  # 1943\n    2.72,  # 1944\n    2.62,  # 1945\n    2.53,  # 1946\n    2.61,  # 1947\n    2.82,  # 1948\n    2.66,  # 1949\n    2.62,  # 1950\n    2.86,  # 1951\n    2.96,  # 1952\n    3.20,  # 1953\n    2.90,  # 1954\n    3.06,  # 1955\n    3.36,  # 1956\n    3.89,  # 1957\n    3.79,  # 1958\n    4.38,  # 1959\n    4.41,  # 1960\n    4.35,  # 1961\n    4.33,  # 1962\n    4.26,  # 1963\n    4.40,  # 1964\n    4.49,  # 1965\n    5.13,  # 1966\n]\n\n# Verify we have 25 years of data\nprint(f\"Number of years: {len(years)}\")\nprint(f\"Years: {years[0]} to {years[-1]}\")\n\n# Calculate correlation coefficient\ncorr, p_value = stats.pearsonr(treasury_yields, moodys_yields)\nprint(f\"\\nCorrelation coefficient: {corr}\")\n\n# Calculate partial correlation controlling for time\n# First, create time variable (centered or raw)\ntime = np.array(years)\n\n# Method: Calculate partial correlation between X and Y controlling for Z\n# Using the formula: r_xy.z = (r_xy - r_xz * r_yz) / sqrt((1-r_xz^2)*(1-r_yz^2))\n\n# Correlation between treasury and time\nr_xy = corr  # treasury and moody's\nr_xz = stats.pearsonr(treasury_yields, time)[0]  # treasury and time\nr_yz = stats.pearsonr(moodys_yields, time)[0]  # moody's and time\n\nprint(f\"\\nCorrelations:\")\nprint(f\"r_xy (treasury vs moody's): {r_xy}\")\nprint(f\"r_xz (treasury vs time): {r_xz}\")\nprint(f\"r_yz (moody's vs time): {r_yz}\")\n\n# Partial correlation formula\npartial_corr = (r_xy - r_xz * r_yz) / np.sqrt((1 - r_xz**2) * (1 - r_yz**2))\n\nprint(f\"\\nPartial correlation (controlling for time): {partial_corr}\")\n\n# Round to nearest thousandths\ncorr_rounded = round(corr, 3)\npartial_corr_rounded = round(partial_corr, 3)\n\nprint(f\"\\nRounded values:\")\nprint(f\"Correlation: {corr_rounded}\")\nprint(f\"Partial correlation: {partial_corr_rounded}\")\n\n# Verify the numbers\nprint(f\"\\nFinal answer: [{corr_rounded}, {partial_corr_rounded}]\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
