  return numerator / denominator\n\n# Calculate correlation coefficient\nr_xy = pearson_correlation(treasury_yields, moodys_yields)\nprint(f\"Correlation coefficient: {r_xy}\")\n\n# Calculate correlations with time\ntime = years\nr_xz = pearson_correlation(treasury_yields, time)  # treasury and time\nr_yz = pearson_correlation(moodys_yields, time)  # moody's and time\n\nprint(f\"\\nCorrelations:\")\nprint(f\"r_xy (treasury vs moody's): {r_xy}\")\nprint(f\"r_xz (treasury vs time): {r_xz}\")\nprint(f\"r_yz (moody's vs time): {r_yz}\")\n\n# Partial correlation formula: r_xy.z = (r_xy - r_xz * r_yz) / sqrt((1-r_xz^2)*(1-r_yz^2))\npartial_corr = (r_xy - r_xz * r_yz) / math.sqrt((1 - r_xz**2) * (1 - r_yz**2))\n\nprint(f\"\\nPartial correlation (controlling for time): {partial_corr}\")\n\n# Round to nearest thousandths\ncorr_rounded = round(r_xy, 3)\npartial_corr_rounded = round(partial_corr, 3)\n\nprint(f\"\\nRounded values:\")\nprint(f\"Correlation: {corr_rounded}\")\nprint(f\"Partial correlation: {partial_corr_rounded}\")\n\n# Final answer\nprint(f\"\\nFinal answer: [{corr_rounded}, {partial_corr_rounded}]\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
